    pub async fn update_occurrence(
        &self,
        actor_user_id: i64,
        is_superadmin: bool,
        calendar_id: i64,
        series_id: i64,
        change: OccurrenceChange,
    ) -> Result<EventProjection, EventServiceError> {
        let OccurrenceChange {
            recurrence_id,
            expected_version,
            event,
        } = change;
        validate_mutation(&event)?;
        let EventTiming::Timed {
            start_utc,
            end_utc,
            timezone,
        } = &event.timing
        else {
            return Err(EventServiceError::InvalidInput);
        };
        timezone
            .parse::<Tz>()
