#[tokio::test]
async fn get_returns_valid_vcalendar_with_stable_url_and_uid() {
    let (
        _temp_dir,
        pool,
        accounts,
        _user_id,
        password,
        principal_id,
        calendar_id,
        _event_id,
        resource_name,
    ) = scenario().await;

    let app = build_caldav_router(accounts);
    let uri = format!("/dav/calendars/{principal_id}/{calendar_id}/{resource_name}.ics");
    let (status, headers, body) = request(
