use std::{
    collections::{HashMap, HashSet},
    fmt::{self, Display, Formatter},
};

use chrono::{DateTime, Duration, LocalResult, NaiveDate, NaiveDateTime, TimeZone, Utc};
use chrono_tz::Tz;

use crate::recurrence::RecurrenceRule;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct IcsParserLimits {
    pub max_components: usize,
    pub max_events: usize,
    pub max_component_bytes: usize,
    pub max_text_bytes: usize,
    pub max_recurrence_values: usize,
}

impl Default for IcsParserLimits {
    fn default() -> Self {
        Self {
            max_components: 1_000,
            max_events: 500,
            max_component_bytes: 256 * 1024,
            max_text_bytes: 16 * 1024,
            max_recurrence_values: 1_000,
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct NormalizedCalendar {
    pub events: Vec<NormalizedEvent>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct NormalizedEvent {
    pub uid: String,
    pub timing: NormalizedTiming,
    pub summary: String,
    pub description: Option<String>,
    pub location: Option<String>,
    pub status: Option<String>,
    pub rrule: Option<String>,
    pub exdates: Vec<NormalizedDateValue>,
    pub recurrence_id: Option<NormalizedDateValue>,
    pub sequence: u64,
    pub dtstamp: Option<DateTime<Utc>>,
    pub last_modified: Option<DateTime<Utc>>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum NormalizedTiming {
    Timed {
        starts_at: DateTime<Utc>,
        ends_at: DateTime<Utc>,
        timezone: Option<String>,
    },
    AllDay {
        start_date: NaiveDate,
        end_date: NaiveDate,
    },
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
pub enum NormalizedDateValue {
    Timed(DateTime<Utc>),
    AllDay(NaiveDate),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum IcsParseErrorCode {
    Malformed,
    InvalidEvent,
    LimitExceeded,
    DuplicateEvent,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct IcsParseError {
    code: IcsParseErrorCode,
}
impl IcsParseError {
    fn new(code: IcsParseErrorCode) -> Self {
        Self { code }
    }
    pub fn code(&self) -> IcsParseErrorCode {
        self.code
    }
}
impl Display for IcsParseError {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        f.write_str("invalid calendar data")
    }
}
impl std::error::Error for IcsParseError {}

pub fn parse_calendar(
    input: &str,
    limits: IcsParserLimits,
) -> Result<NormalizedCalendar, IcsParseError> {
    if limits.max_components == 0
        || limits.max_events == 0
        || limits.max_component_bytes == 0
        || limits.max_text_bytes == 0
        || limits.max_recurrence_values == 0
    {
        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
    }
    let lines = unfold(input)?;
    let mut stack = Vec::new();
    let mut components = 0_usize;
    let mut current: Option<Vec<Property>> = None;
    let mut events = Vec::new();
    let mut keys = HashSet::new();
    for line in lines {
        let property = property(&line)?;
        match (property.name.as_str(), property.value.as_str()) {
            ("BEGIN", name) => {
                components += 1;
                if components > limits.max_components {
                    return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
                }
                if name != "VCALENDAR"
                    && name != "VEVENT"
                    && name != "VTIMEZONE"
                    && name != "STANDARD"
                    && name != "DAYLIGHT"
                {
                    return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
                }
                if name == "VCALENDAR" && !stack.is_empty() {
                    return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
                }
                if name == "VEVENT" && stack.last().map(String::as_str) != Some("VCALENDAR") {
                    return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
                }
                if name == "VEVENT" {
                    current = Some(Vec::new());
                }
                stack.push(name.to_owned());
            }
            ("END", name) => {
                if stack.pop().as_deref() != Some(name) {
                    return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
                }
                if name == "VEVENT" {
                    let event = normalize_event(
                        current
                            .take()
                            .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?,
                        limits,
                    )?;
                    let key = (event.uid.clone(), event.recurrence_id.clone());
                    if !keys.insert(key) {
                        return Err(IcsParseError::new(IcsParseErrorCode::DuplicateEvent));
                    }
                    events.push(event);
                    if events.len() > limits.max_events {
                        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
                    }
                }
            }
            _ => {
                if stack.last().map(String::as_str) == Some("VEVENT") {
                    let target = current
                        .as_mut()
                        .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?;
                    let bytes = target.iter().map(|p| p.raw_len).sum::<usize>() + property.raw_len;
                    if bytes > limits.max_component_bytes {
                        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
                    }
                    target.push(property);
                }
            }
        }
    }
    if !stack.is_empty() || events.is_empty() {
        return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
    }
    Ok(NormalizedCalendar { events })
}

#[derive(Clone)]
struct Property {
    name: String,
    params: HashMap<String, String>,
    value: String,
    raw_len: usize,
}
fn unfold(input: &str) -> Result<Vec<String>, IcsParseError> {
    let mut lines: Vec<String> = Vec::new();
    for raw in input.lines() {
        let line = raw.strip_suffix('\r').unwrap_or(raw);
        if line.starts_with(' ') || line.starts_with('\t') {
            lines
                .last_mut()
                .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?
                .push_str(&line[1..]);
        } else if !line.is_empty() {
            lines.push(line.to_owned());
        }
    }
    if lines.is_empty() {
        return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
    }
    Ok(lines)
}
fn property(line: &str) -> Result<Property, IcsParseError> {
    let (left, value) = line
        .split_once(':')
        .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?;
    let mut parts = left.split(';');
    let name = parts.next().unwrap().to_ascii_uppercase();
    if name.is_empty() || !name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') {
        return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
    }
    let mut params = HashMap::new();
    for part in parts {
        let (key, value) = part
            .split_once('=')
            .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?;
        if params
            .insert(key.to_ascii_uppercase(), value.trim_matches('"').to_owned())
            .is_some()
        {
            return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
        }
    }
    Ok(Property {
        name,
        params,
        value: value.to_owned(),
        raw_len: line.len(),
    })
}

fn normalize_event(
    properties: Vec<Property>,
    limits: IcsParserLimits,
) -> Result<NormalizedEvent, IcsParseError> {
    let mut fields: HashMap<String, Vec<Property>> = HashMap::new();
    for p in properties {
        fields.entry(p.name.clone()).or_default().push(p);
    }
    for name in [
        "UID",
        "DTSTART",
        "DTEND",
        "DURATION",
        "SUMMARY",
        "DESCRIPTION",
        "LOCATION",
        "STATUS",
        "RRULE",
        "RECURRENCE-ID",
        "SEQUENCE",
        "DTSTAMP",
        "LAST-MODIFIED",
    ] {
        if fields.get(name).is_some_and(|values| values.len() > 1) {
            return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
        }
    }
    let one = |name: &str| fields.get(name).and_then(|v| v.first());
    let uid = text(
        one("UID").ok_or(IcsParseError::new(IcsParseErrorCode::InvalidEvent))?,
        limits,
    )?;
    if uid.is_empty() {
        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
    }
    let start =
        date_value(one("DTSTART").ok_or(IcsParseError::new(IcsParseErrorCode::InvalidEvent))?)?;
    let end = one("DTEND").map(date_value).transpose()?;
    let duration = one("DURATION")
        .map(|p| parse_duration(&p.value))
        .transpose()?;
    if end.is_some() == duration.is_some() {
        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
    }
    let timezone = one("DTSTART").and_then(|p| p.params.get("TZID")).cloned();
    if let Some(end_property) = one("DTEND")
        && end_property.params.get("TZID").cloned() != timezone
    {
        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
    }
    let timing = timing(start, end, duration, timezone)?;
    let recurrence_id = one("RECURRENCE-ID").map(date_value).transpose()?;
    if recurrence_id
        .as_ref()
        .is_some_and(|v| !same_kind(v, &timing))
    {
        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
    }
    let mut exdates = Vec::new();
    for p in fields.get("EXDATE").into_iter().flatten() {
        for value in p.value.split(',') {
            let copied = Property {
                value: value.to_owned(),
                ..p.clone()
            };
            let value = date_value(&copied)?;
            if !same_kind(&value, &timing) {
                return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
            }
            exdates.push(value);
            if exdates.len() > limits.max_recurrence_values {
                return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
            }
        }
    }
    let rrule = one("RRULE").map(|p| p.value.clone());
    if let Some(rule) = &rrule {
        if rule.split(';').count() > limits.max_recurrence_values {
            return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
        }
        if RecurrenceRule::parse(rule).is_err() {
            return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
        }
    }
    let status = one("STATUS").map(|p| p.value.clone());
    if status
        .as_deref()
        .is_some_and(|s| !matches!(s, "CONFIRMED" | "TENTATIVE" | "CANCELLED"))
    {
        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
    }
    Ok(NormalizedEvent {
        uid,
        timing,
        summary: one("SUMMARY")
            .map(|p| text(p, limits))
            .transpose()?
            .unwrap_or_default(),
        description: one("DESCRIPTION").map(|p| text(p, limits)).transpose()?,
        location: one("LOCATION").map(|p| text(p, limits)).transpose()?,
        status,
        rrule,
        exdates,
        recurrence_id,
        sequence: one("SEQUENCE")
            .map(|p| p.value.parse())
            .transpose()
            .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent))?
            .unwrap_or(0),
        dtstamp: one("DTSTAMP").map(utc_datetime).transpose()?,
        last_modified: one("LAST-MODIFIED").map(utc_datetime).transpose()?,
    })
}
fn text(p: &Property, limits: IcsParserLimits) -> Result<String, IcsParseError> {
    if p.value.len() > limits.max_text_bytes {
        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
    }
    let mut out = String::new();
    let mut escaped = false;
    for c in p.value.chars() {
        if escaped {
            out.push(match c {
                'n' | 'N' => '\n',
                '\\' => '\\',
                ',' => ',',
                ';' => ';',
                _ => return Err(IcsParseError::new(IcsParseErrorCode::Malformed)),
            });
            escaped = false;
        } else if c == '\\' {
            escaped = true;
        } else {
            out.push(c);
        }
    }
    if escaped || out.len() > limits.max_text_bytes {
        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
    }
    Ok(out)
}
fn date_value(p: &Property) -> Result<NormalizedDateValue, IcsParseError> {
    if p.params.get("VALUE").is_some_and(|v| v != "DATE") {
        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
    }
    if p.params.get("VALUE").is_some_and(|v| v == "DATE") || p.value.len() == 8 {
        return NaiveDate::parse_from_str(&p.value, "%Y%m%d")
            .map(NormalizedDateValue::AllDay)
            .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent));
    }
    let naive = NaiveDateTime::parse_from_str(p.value.trim_end_matches('Z'), "%Y%m%dT%H%M%S")
        .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent))?;
    let value = if p.value.ends_with('Z') {
        naive.and_utc()
    } else if let Some(tz) = p.params.get("TZID") {
        let tz: Tz = tz
            .parse()
            .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent))?;
        match tz.from_local_datetime(&naive) {
            LocalResult::Single(v) => v.with_timezone(&Utc),
            _ => return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent)),
        }
    } else {
        naive.and_utc()
    };
    Ok(NormalizedDateValue::Timed(value))
}
fn timing(
    start: NormalizedDateValue,
    end: Option<NormalizedDateValue>,
    duration: Option<Duration>,
    timezone: Option<String>,
) -> Result<NormalizedTiming, IcsParseError> {
    match (start, end, duration) {
        (NormalizedDateValue::Timed(s), Some(NormalizedDateValue::Timed(e)), None) if e > s => {
            Ok(NormalizedTiming::Timed {
                starts_at: s,
                ends_at: e,
                timezone,
            })
        }
        (NormalizedDateValue::Timed(s), None, Some(d)) if d > Duration::zero() => {
            Ok(NormalizedTiming::Timed {
                starts_at: s,
                ends_at: s + d,
                timezone,
            })
        }
        (NormalizedDateValue::AllDay(s), Some(NormalizedDateValue::AllDay(e)), None)
            if e > s && timezone.is_none() =>
        {
            Ok(NormalizedTiming::AllDay {
                start_date: s,
                end_date: e,
            })
        }
        (NormalizedDateValue::AllDay(s), None, Some(d))
            if d > Duration::zero() && d.num_seconds() % 86_400 == 0 && timezone.is_none() =>
        {
            Ok(NormalizedTiming::AllDay {
                start_date: s,
                end_date: s
                    .checked_add_signed(d)
                    .ok_or(IcsParseError::new(IcsParseErrorCode::InvalidEvent))?,
            })
        }
        _ => Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent)),
    }
}
fn parse_duration(value: &str) -> Result<Duration, IcsParseError> {
    if !value.starts_with('P') || value.contains('-') {
        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
    }
    let mut seconds = 0_i64;
    let mut n = String::new();
    for ch in value[1..].chars() {
        if ch.is_ascii_digit() {
            n.push(ch);
            continue;
        }
        if ch == 'T' {
            continue;
        }
        let number: i64 = n
            .parse()
            .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent))?;
        n.clear();
        seconds = seconds
            .checked_add(match ch {
                'W' => number * 604_800,
                'D' => number * 86_400,
                'H' => number * 3_600,
                'M' => number * 60,
                'S' => number,
                _ => return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent)),
            })
            .ok_or(IcsParseError::new(IcsParseErrorCode::InvalidEvent))?;
    }
    if !n.is_empty() || seconds <= 0 {
        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
    }
    Ok(Duration::seconds(seconds))
}
fn utc_datetime(p: &Property) -> Result<DateTime<Utc>, IcsParseError> {
    if !p.value.ends_with('Z') || p.params.contains_key("TZID") {
        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
    }
    match date_value(p)? {
        NormalizedDateValue::Timed(v) => Ok(v),
        _ => Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent)),
    }
}
fn same_kind(value: &NormalizedDateValue, timing: &NormalizedTiming) -> bool {
    matches!(
        (value, timing),
        (
            NormalizedDateValue::Timed(_),
            NormalizedTiming::Timed { .. }
        ) | (
            NormalizedDateValue::AllDay(_),
            NormalizedTiming::AllDay { .. }
        )
    )
}

use commoncal_backend::{
    admin::AdminService,
    admin_invitation_rate_limit::AdminInvitationRateLimiterState,
    backup::{Aes256GcmEncryptor, BackupCommand, BackupService, RestoreCommand, RestoreService},
    bootstrap::{BootstrapCommand, InitialSuperadminBootstrap},
    caldav::{
        auth::CaldavAccountService,
        http::{build_caldav_router, build_connection_management_router},
    },
    calendar::CalendarService,
    config::{AppConfig, Environment},
    database::{connect_and_migrate, connect_read_only},
    email::DevelopmentEmailSender,
    event::EventService,
    external_feed::ExternalFeedService,
    http::{
        Readiness, ResponseSecurityConfig,
        build_router_with_auth_flows_sessions_admin_calendars_views_and_external_feeds,
        secure_responses, serve_frontend,
    },
    invitations::InvitationConsumer,
    login::{FixedWindowLoginRateLimiter, LoginService},
    notification::NotificationWorker,
    public_rate_limit::PublicRateLimiterState,
    rate_limiter::FixedWindowRateLimiter,
    security::SecretKey,
    sessions::{SessionManager, SessionSecurityConfig},
    shared_view::SharedViewService,
    user_invitation::UserInvitationService,
    user_invitation_rate_limit::{
        USER_INVITATION_MAX_REQUESTS, USER_INVITATION_WINDOW_SECONDS,
        UserInvitationRateLimiterState,
    },
    write_rate_limit::WriteRateLimiterState,
};
use std::{
    net::SocketAddr,
    sync::Arc,
    time::{SystemTime, UNIX_EPOCH},
};
use tokio::net::TcpListener;
use tracing_subscriber::{EnvFilter, layer::SubscriberExt, util::SubscriberInitExt};
use url::Url;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    init_tracing();
    let config = AppConfig::from_env()?;
    let arguments: Vec<String> = std::env::args().skip(1).collect();
    if arguments.first().is_some_and(|value| value == "restore") {
        return run_restore(&config, &arguments[1..]).await;
    }
    if arguments.first().is_some_and(|value| value == "backup") {
        let database = connect_read_only(&config).await?;
        return run_backup(database, &arguments[1..]).await;
    }

    let readiness = Readiness::new();
    let database = connect_and_migrate(&config, readiness.clone()).await?;

    if arguments
        .first()
        .is_some_and(|value| value == "bootstrap-superadmin")
    {
        return run_bootstrap(&config, database, &arguments[1..]).await;
    }
    if arguments.first().is_some_and(|value| value == "seed") {
        return run_seed(&config, database).await;
    }
    if !arguments.is_empty() {
        return Err(format!("unknown command: {}", arguments[0]).into());
    }

    let listener = TcpListener::bind(config.bind_address).await?;

    tracing::info!(
        environment = ?config.environment,
        address = %config.bind_address,
        "server started"
    );

    let secret_key = config
        .session_secret()
        .map(|secret| SecretKey::derive(secret.as_bytes()))
        .unwrap_or_else(SecretKey::generate);
    let invitation_consumer =
        InvitationConsumer::new(database.clone(), secret_key.clone(), 30 * 24 * 60 * 60);
    let email_sender = Arc::new(DevelopmentEmailSender::new());
    let is_secure = config.app_origin().starts_with("https://");
    let login_service = LoginService::new(
        database.clone(),
        secret_key.clone(),
        15 * 60,
        30 * 24 * 60 * 60,
        "/login",
        email_sender.clone(),
        Arc::new(FixedWindowLoginRateLimiter::new(5, 15 * 60)),
        is_secure,
    );
    let session_manager = SessionManager::new(
        database.clone(),
        secret_key.clone(),
        SessionSecurityConfig::new(7 * 24 * 60 * 60, 5 * 60, config.app_origin())?,
    );
    let admin_service = AdminService::with_email_sender(
        database.clone(),
        secret_key.clone(),
        24 * 60 * 60,
        format!("{}/invitations/accept", config.app_origin()),
        email_sender.clone(),
    );
    let calendar_service = CalendarService::new(database.clone());
    let notification_service =
        commoncal_backend::notification::NotificationService::new(database.clone());
    let notification_worker_database = database.clone();
    let notification_worker_sender = email_sender.clone();
    tokio::spawn(async move {
        let mut tick = tokio::time::interval(std::time::Duration::from_secs(30));
        loop {
            tick.tick().await;
            let now = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .expect("system clock is before Unix epoch")
                .as_secs() as i64;
            let worker = NotificationWorker::new_at_with_email_sender(
                notification_worker_database.clone(),
                now,
                5 * 60,
                100,
                notification_worker_sender.clone(),
            );
            if worker.process_due().await.is_err() {
                tracing::error!(error_code = "notification_worker_failed");
            }
        }
    });
    let notification_replanner = notification_service.clone();
    let event_service = EventService::new_with_notification_replanner(
        database.clone(),
        Arc::new(move |event_id| {
            let notifications = notification_replanner.clone();
            tokio::spawn(async move {
                if notifications.replan_event(event_id).await.is_err() {
                    tracing::error!(error_code = "notification_replan_failed");
                }
            });
        }),
    );
    let external_feed_service = ExternalFeedService::new(database.clone(), secret_key.clone());
    let shared_view_service = SharedViewService::new_with_key(database.clone(), secret_key.clone());
    let caldav_public_origin = Url::parse(config.caldav_public_origin())
        .expect("CALDAV_PUBLIC_ORIGIN is validated as a well-formed origin");
    let caldav_accounts =
        CaldavAccountService::new(database.clone(), secret_key.clone(), caldav_public_origin);

    let write_rate_limiter = if std::env::var("APP_ENV").ok().as_deref() == Some("development") {
        None
    } else {
        Some(WriteRateLimiterState {
            limiter: Arc::new(FixedWindowRateLimiter::new(30, 60)),
        })
    };

    let public_rate_limiter = if std::env::var("APP_ENV").ok().as_deref() == Some("development") {
        None
    } else {
        Some(PublicRateLimiterState {
            limiter: Arc::new(FixedWindowRateLimiter::new(100, 60)),
        })
    };

    let admin_rate_limiter = if std::env::var("APP_ENV").ok().as_deref() == Some("production") {
        let limiter = FixedWindowRateLimiter::new(5, 60);
        Some(AdminInvitationRateLimiterState {
            limiter: Arc::new(limiter),
        })
    } else {
        None
    };

    let user_invitation_rate_limiter =
        if std::env::var("APP_ENV").ok().as_deref() == Some("production") {
            let limiter = FixedWindowRateLimiter::new(
                USER_INVITATION_MAX_REQUESTS,
                USER_INVITATION_WINDOW_SECONDS,
            );
            Some(UserInvitationRateLimiterState {
                limiter: Arc::new(limiter),
            })
        } else {
            None
        };

    let user_invitation_service = UserInvitationService::with_email_sender(
        database.clone(),
        secret_key.clone(),
        24 * 60 * 60,
        format!("{}/invitations/accept", config.app_origin()),
        email_sender.clone(),
    );
    let caldav_session_manager = session_manager.clone();

    let mut router = build_router_with_auth_flows_sessions_admin_calendars_views_and_external_feeds(
        readiness,
        invitation_consumer,
        login_service,
        session_manager,
        admin_service,
        calendar_service,
        event_service,
        shared_view_service,
        external_feed_service,
        notification_service,
        config.access_log_level(),
        is_secure,
        config.password_login_enabled(),
        write_rate_limiter,
        public_rate_limiter,
        admin_rate_limiter,
        user_invitation_service,
        user_invitation_rate_limiter,
    );

    // Add MCP internal API routes (separate router with its own state).
    // The internal API key is required in production; startup fails when it is
    // absent or empty so the boundary can never be left open.
    let mcp_internal_api_key = std::env::var("MCP_INTERNAL_API_KEY").unwrap_or_default();
    if config.environment == Environment::Production && mcp_internal_api_key.is_empty() {
        return Err("MCP_INTERNAL_API_KEY is required in production".into());
    }
    let mcp_router = commoncal_backend::mcp_internal::build_mcp_internal_router(
        database.clone(),
        commoncal_backend::mcp_internal::McpApiKeyAuth::new(mcp_internal_api_key),
    );
    router = router.merge(mcp_router);

    // Add McpGrant management routes (frontend-facing).
    let db_pool = database.clone();
    let mcp_grant_router = axum::Router::new()
        .route(
            "/api/v1/mcp-grants",
            axum::routing::get(commoncal_backend::mcp_grant_management::list_mcp_grants),
        )
        .route(
            "/api/v1/mcp-grants",
            axum::routing::post(commoncal_backend::mcp_grant_management::create_mcp_grant),
        )
        .route(
            "/api/v1/mcp-grants/:id",
            axum::routing::patch(commoncal_backend::mcp_grant_management::update_mcp_grant),
        )
        .route(
            "/api/v1/mcp-grants/:id",
            axum::routing::delete(commoncal_backend::mcp_grant_management::revoke_mcp_grant),
        )
        .route(
            "/api/v1/mcp-grants/:id/resend",
            axum::routing::post(
                commoncal_backend::mcp_grant_management::resend_mcp_grant_confirmation,
            ),
        )
        .with_state(db_pool);
    router = router.merge(mcp_grant_router);

    // Add CalDAV DAV router (isolated, Basic-auth, no browser session/CSRF).
    router = router.merge(build_caldav_router(caldav_accounts.clone()));
    // Add CalDAV connection-management browser API (cookie + CSRF protected).
    router = router.merge(build_connection_management_router(
        caldav_accounts,
        caldav_session_manager,
    ));

    let frontend_directory =
        std::env::var("FRONTEND_DIR").unwrap_or_else(|_| "/app/frontend".into());

    let response_security = if config.environment == Environment::Production
        && config.app_origin().starts_with("https://")
    {
        ResponseSecurityConfig::production_https()
    } else {
        ResponseSecurityConfig::local_http()
    };

    axum::serve(
        listener,
        secure_responses(
            serve_frontend(router, frontend_directory),
            response_security,
        )
        .into_make_service_with_connect_info::<SocketAddr>(),
    )
    .with_graceful_shutdown(shutdown_signal())
    .await?;

    Ok(())
}

async fn run_backup(
    database: sqlx::SqlitePool,
    arguments: &[String],
) -> Result<(), Box<dyn std::error::Error>> {
    let command = BackupCommand::from_arguments(arguments)?;
    let created_at = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() as i64;
    let encryption_key = std::env::var("BACKUP_ENCRYPTION_KEY_HEX")
        .map_err(|_| "BACKUP_ENCRYPTION_KEY_HEX is required for backup")?;
    let encryptor = Aes256GcmEncryptor::from_hex_key(&encryption_key)?;
    let metadata = BackupService::new(database)
        .create_encrypted_and_upload(command.destination_directory, created_at, &encryptor, None)
        .await?;
    println!("backup_id={}", metadata.id);
    println!("artifact_path={}", metadata.artifact_path.display());
    println!("snapshot_sha256={}", metadata.snapshot_sha256);
    println!("compressed_sha256={}", metadata.compressed_sha256);
    Ok(())
}

async fn run_restore(
    config: &AppConfig,
    arguments: &[String],
) -> Result<(), Box<dyn std::error::Error>> {
    let command = RestoreCommand::from_arguments(arguments)?;
    if config.environment == Environment::Production {
        command.refuse_production_target(config.database_path())?;
    }
    let encryption_key = std::env::var("BACKUP_ENCRYPTION_KEY_HEX")
        .map_err(|_| "BACKUP_ENCRYPTION_KEY_HEX is required for restore")?;
    let encryptor = Aes256GcmEncryptor::from_hex_key(&encryption_key)?;
    RestoreService::restore_encrypted(
        command.artifact_path,
        command.destination_database.clone(),
        &encryptor,
    )
    .await?;
    println!(
        "restored_database={}",
        command.destination_database.display()
    );
    Ok(())
}

async fn run_bootstrap(
    config: &AppConfig,
    database: sqlx::SqlitePool,
    arguments: &[String],
) -> Result<(), Box<dyn std::error::Error>> {
    if !(1..=2).contains(&arguments.len()) {
        return Err("usage: commoncal-backend bootstrap-superadmin <email> [display-name]".into());
    }
    let secret = config
        .session_secret()
        .filter(|value| !value.is_empty())
        .ok_or("SESSION_SECRET is required for bootstrap-superadmin")?;
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() as i64;
    let result = InitialSuperadminBootstrap::new(database, SecretKey::derive(secret.as_bytes()))
        .execute(BootstrapCommand {
            normalized_email: arguments[0].clone(),
            display_name: arguments.get(1).cloned(),
            created_at: now,
            expires_at: now + 24 * 60 * 60,
        })
        .await?;

    println!("invitation_id={}", result.invitation_id);
    println!("token={}", result.token.expose());
    Ok(())
}

async fn run_seed(
    config: &AppConfig,
    database: sqlx::SqlitePool,
) -> Result<(), Box<dyn std::error::Error>> {
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() as i64;

    // Check if user already exists
    let mut tx = database.begin().await?;
    let user_count: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM users")
        .fetch_one(&mut *tx)
        .await?;

    if user_count > 0 {
        println!("database already has {} user(s), skipping seed", user_count);
        return Ok(());
    }

    // Allow seed in production only when DEFAULT_ADMIN_PASSWORD is set.
    if config.environment == Environment::Production
        && std::env::var("DEFAULT_ADMIN_PASSWORD")
            .ok()
            .filter(|v| !v.is_empty())
            .is_none()
    {
        return Err(
            "seed command is not allowed in production without DEFAULT_ADMIN_PASSWORD".into(),
        );
    }

    // Create user
    let user_id: i64 = sqlx::query_scalar(
        "INSERT INTO users (normalized_email, display_name, status, is_superadmin, created_at)
         VALUES ('dev@example.com', 'Dev User', 'active', 1, ?)
         RETURNING id",
    )
    .bind(now)
    .fetch_one(&database)
    .await?;

    // Optionally set password from DEFAULT_ADMIN_PASSWORD env var.
    if let Ok(password) = std::env::var("DEFAULT_ADMIN_PASSWORD")
        && !password.is_empty()
    {
        let hash = bcrypt::hash(&password, bcrypt::DEFAULT_COST)
            .map_err(|e| format!("bcrypt hash failed: {e}"))?;
        sqlx::query("UPDATE users SET password_hash = ? WHERE id = ?")
            .bind(&hash)
            .bind(user_id)
            .execute(&database)
            .await?;
        println!("  password:  set (from DEFAULT_ADMIN_PASSWORD)");
    }

    // Create calendar
    let calendar_id: i64 = sqlx::query_scalar(
        "INSERT INTO calendars (owner_user_id, name, color, default_timezone, default_event_visibility, created_at, updated_at)
         VALUES (?, 'My Calendar', '#3b82f6', 'UTC', 'default', ?, ?)
         RETURNING id",
    )
    .bind(user_id)
    .bind(now)
    .bind(now)
    .fetch_one(&database)
    .await?;

    // Create calendar_acl
    sqlx::query(
