        Some(PlatformRole::User),
        Some(role),
        CalendarAction::CreateEvent,
    ) != AuthorizationDecision::Allow
    {
        return dav_resource_not_found();
    }

    let body = match axum::body::to_bytes(request.into_body(), query::MAX_BODY_BYTES).await {
        Ok(body) => body,
        Err(_) => return dav_bad_request("request body too large"),
    };
    let body_str = match std::str::from_utf8(&body) {
        Ok(value) => value,
        Err(_) => return dav_bad_request("request body must be UTF-8"),
    };
