            (header::ETAG, etag),
            (header::CONTENT_TYPE, "text/calendar; charset=utf-8"),
        ],
        ical,
    )
        .into_response()
}

fn dav_capabilities() -> Response {
    (
        StatusCode::OK,
        [(DAV, DAV_CAPABILITIES), (header::ALLOW, DAV_ALLOW)],
    )
        .into_response()
